        <div style={{
          opacity: chartP,
          transform: `translateY(${interpolate(chartP, [0,1], [58, 0])}px) scale(${interpolate(chartP, [0,1], [0.94, 1])})`,
          width: chartW,
        }}>
          <div style={{
            backgroundColor: "rgba(255,255,255,0.03)",
            border: "1px solid rgba(255,255,255,0.09)",
            borderRadius: 32, padding: "42px 42px 30px",
            boxShadow: "0 24px 70px rgba(0,0,0,0.3)",
          }}>
            <svg width={chartW - 84} height={chartH} style={{ overflow: "visible" }}>
              {[0, 25, 50, 75, 100].map(pct => {
                const y = getY((pct / 100) * maxVal);
                return <line key={pct} x1={padL} y1={y} x2={innerW + padL} y2={y} stroke="rgba(255,255,255,0.06)" strokeWidth={1} />;
              })}
              {TREND_LINES.map(line => {
                const visible = Math.floor(1 + drawProgress * (line.points.length - 1));
                const pts     = line.points.slice(0, visible + 1);
                const pathD   = pts.map((val, i) => `${i === 0 ? "M" : "L"} ${getX(i, line.points.length)} ${getY(val)}`).join(" ");
                return (
                  <g key={line.id}>
                    <path d={pathD} stroke={line.color} strokeWidth={line.id === "you" ? 5 : 3.5}
                      fill="none" strokeLinecap="round" strokeLinejoin="round"
                      opacity={line.id === "you" ? 1 : 0.7} />
                    {pts.length > 1 && (
                      <circle
                        cx={getX(pts.length - 1, line.points.length)}
                        cy={getY(pts[pts.length - 1])}
                        r={11} fill={line.color}
                        style={{ filter: `drop-shadow(0 0 9px ${line.color})` }}
                      />
                    )}
                  </g>
                );
              })}
            </svg>

            <div style={{ display: "flex", gap: 30, marginTop: 32, flexWrap: "wrap" }}>
              {TREND_LINES.map((line, i) => (
                <div key={line.id} style={{
                  display: "flex", alignItems: "center", gap: 16,
                  padding: "20px 26px",
                  backgroundColor: line.id === "you" ? "rgba(0,170,255,0.09)" : "rgba(255,255,255,0.03)",
                  border: `1px solid ${line.color}42`, borderRadius: 18,
                  opacity: annotPs[i],
                  transform: `translateY(${interpolate(annotPs[i], [0,1], [26, 0])}px) scale(${interpolate(annotPs[i], [0,1], [0.9, 1])})`,
                }}>
                  <div style={{ width: 44, height: 5, backgroundColor: line.color, borderRadius: 3, flexShrink: 0, boxShadow: `0 0 12px ${line.color}` }} />
                  <div>
                    <div style={{ fontSize: 22, fontWeight: 700, color: line.color }}>{line.label}</div>
                    <div style={{ fontSize: 19, color: COLORS.muted, marginTop: 4 }}>
                      cited <span style={{ fontWeight: 700, color: line.color }}>{line.cited}x</span> this month
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

