const Phase6CBar: React.FC<{ item: (typeof FORMAT_DATA)[number]; delay: number }> = ({ item, delay }) => {
  const frame = useCurrentFrame();
  const { fps: f } = useVideoConfig();
  const progress   = spring({ frame, fps: f, delay,        config: { damping: 150 } });
  const checkP     = spring({ frame, fps: f, delay: delay + 28, config: { damping: 180 } });

  const shimmerX = item.isWinner
    ? interpolate(frame, [60, 160], [-20, 100], { extrapolateLeft: "clamp", extrapolateRight: "clamp" })
    : 0;

  return (
    <div style={{
      display: "flex", alignItems: "center", gap: 32,
      marginBottom: 34, opacity: progress,
      transform: `translateX(${interpolate(progress, [0,1], [-50, 0])}px) scale(${interpolate(progress, [0,1], [0.96, 1])})`,
    }}>
      <div style={{ width: 230, fontSize: 26, fontWeight: 600, color: item.isWinner ? COLORS.white : COLORS.muted, textAlign: "right", flexShrink: 0 }}>
        {item.label}
      </div>
      <div style={{
        flex: 1, height: 76, backgroundColor: "rgba(255,255,255,0.05)",
        borderRadius: 16, overflow: "hidden", position: "relative",
      }}>
        <div style={{
          width: `${item.value * progress}%`, height: "100%",
          background: item.isWinner ? `linear-gradient(90deg, ${COLORS.blue}, ${COLORS.green})` : "rgba(100,116,139,0.4)",
          borderRadius: 16,
          boxShadow: item.isWinner ? "0 0 36px rgba(0,170,255,0.38)" : "none",
        }} />
        {item.isWinner && (
          <div style={{
            position: "absolute", top: 0, left: `${shimmerX}%`,
            width: "20%", height: "100%",
            background: "linear-gradient(90deg, transparent, rgba(255,255,255,0.17), transparent)",
            borderRadius: 16,
          }} />
        )}
      </div>
      <div style={{ width: 96, fontSize: 26, fontWeight: 700, color: item.isWinner ? COLORS.green : COLORS.muted, flexShrink: 0 }}>
        {Math.round(item.value * progress)}%
      </div>
      {item.isWinner && (
        <div style={{
          width: 62, height: 62, borderRadius: "50%",
          backgroundColor: "rgba(74,222,128,0.18)",
          border: "2px solid rgba(74,222,128,0.55)",
          display: "flex", alignItems: "center", justifyContent: "center",
          opacity: checkP,
          transform: `scale(${interpolate(checkP, [0,1], [0,1])}) rotate(${interpolate(checkP, [0,1], [-90, 0])}deg)`,
          flexShrink: 0, boxShadow: "0 0 24px rgba(74,222,128,0.28)",
        }}>
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none">
            <path d="M20 6L9 17l-5-5" stroke={COLORS.green} strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
        </div>
      )}
    </div>
  );
};

